(*
================================================================================
 File        : HMIMappingCyclic.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-03-19
 Version     : V0.01
 Description :
    Zyklische Übergabe von Ein-/Ausgängen und aufbereiteten Messwerten an die HMI.

    Dieses Programm trennt bewusst zwischen:
      - Hardware-/Prozessabbild
      - interner Programmlogik
      - Visualisierungsdaten

    Die HMI liest ausschließlich die hier beschriebenen HMI-Variablen.
    Dadurch bleibt die Visualisierung von der eigentlichen I/O-Anbindung entkoppelt.

================================================================================
 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author          | Description
--------------------------------------------------------------------------------
 V0.01   | 2026-03-19 | RIG Automation  | Initialerstellung HMI-Mapping für
                                        | digitale/analoge Ein- und Ausgänge
================================================================================
*)

(*
===============================================================================
 HMI-DATEN ZYKLISCH AKTUALISIEREN
-------------------------------------------------------------------------------
 Alle für die Visualisierung relevanten Ein- und Ausgangswerte werden in
 sprechende HMI-Variablen kopiert.
===============================================================================
*)

(*
---------------------------------------------------------------------------
Standard-Filterzeiten
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.FilterzeitFrischluft := Sensoren_FilterzeitFrischluft;
gBetriebsparameter.Sensoren.FilterzeitAbluft := Sensoren_FilterzeitAbluft;
gBetriebsparameter.Sensoren.FilterzeitTrockenluft := Sensoren_FilterzeitTrockenluft;
gBetriebsparameter.Sensoren.FilterzeitStocktemp := Sensoren_FilterzeitStocktemp;

(*
---------------------------------------------------------------------------
Messbereiche Frischluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.FrischlTempMessberMin := Sensoren_FrischlTempMessberMin;
gBetriebsparameter.Sensoren.FrischlTempMessberMax := Sensoren_FrischlTempMessberMax;
gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin := Sensoren_FrischlFeuchteMessberMin;
gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax := Sensoren_FrischlFeuchteMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Abluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.AbluftTempMessberMin := Sensoren_AbluftTempMessberMin;
gBetriebsparameter.Sensoren.AbluftTempMessberMax := Sensoren_AbluftTempMessberMax;
gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin := Sensoren_AbluftFeuchtMessberMin;
gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax := Sensoren_AbluftFeuchtMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Trockenluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.TrockenlTempMessberMin := Sensoren_TrockenlTempMessberMin;
gBetriebsparameter.Sensoren.TrockenlTempMessberMax := Sensoren_TrockenlTempMessberMax;
gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin := Sensoren_TrockenlFeuchtMessberMin;
gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax := Sensoren_TrockenlFeuchtMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Stocktemperatur
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.StocktempMessberMin := Sensoren_StockTempMessberMin;
gBetriebsparameter.Sensoren.StocktempMessberMax := Sensoren_StockTempMessberMax;

(*
---------------------------------------------------------------------------
Sensor-Offsets
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.OffsetFrischluftTemp := Sensoren_OffsetFrischluftTemp;
gBetriebsparameter.Sensoren.OffsetFrischluftFeuchte := Sensoren_OffsetFrischluftFeuchte;
gBetriebsparameter.Sensoren.OffsetAbluftBox1Temp := Sensoren_OffsetAbluftBox1Temp;
gBetriebsparameter.Sensoren.OffsetAbluftBox1Feuchte := Sensoren_OffsetAbluftBox1Feuchte;
gBetriebsparameter.Sensoren.OffsetAbluftBox2Temp := Sensoren_OffsetAbluftBox2Temp;
gBetriebsparameter.Sensoren.OffsetAbluftBox2Feuchte := Sensoren_OffsetAbluftBox2Feuchte;
gBetriebsparameter.Sensoren.OffsetTrockenluftTemp := Sensoren_OffsetTrockenluftTemp;
gBetriebsparameter.Sensoren.OffsetTrockenluftFeuchte := Sensoren_OffsetTrockenluftFeuchte;
gBetriebsparameter.Sensoren.OffsetStocktemp := Sensoren_OffsetStocktemp;

(*
---------------------------------------------------------------------------
Ausstattung / aktivierte Anlagenteile
---------------------------------------------------------------------------
Diese Werte sind vorläufige Defaultwerte und müssen später an die reale
Anlagenausstattung angepasst werden.
---------------------------------------------------------------------------
*)
gBetriebsparameter.Ausstattung.Box2 := Ausstattung_Box2;
gBetriebsparameter.Ausstattung.Abluftventilator := Ausstattung_Abluftventilator;
gBetriebsparameter.Ausstattung.SensorFrischluft := Ausstattung_SensorFrischluft;
gBetriebsparameter.Ausstattung.SensorAbluftBox1 := Ausstattung_SensorAbluftBox1;
gBetriebsparameter.Ausstattung.SensorAbluftBox2 := Ausstattung_SensorAbluftBox2;
gBetriebsparameter.Ausstattung.SensorTrockenluft := Ausstattung_SensorTrockenluft;
gBetriebsparameter.Ausstattung.SensorStocktemp := Ausstattung_SensorStocktemp;
gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe1 := Ausstattung_EndlagenVhdBoxenklappe1;
gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe2 := Ausstattung_EndlagenVhdBoxenklappe2;
gBetriebsparameter.Ausstattung.Luftaufbereiter := Ausstattung_Luftaufbereiter_Typ <> KEINER;

(*
---------------------------------------------------------------------------
Ventilator
---------------------------------------------------------------------------
*)
gBetriebsparameter.Ventilator.DrehzahlMin := Par_Ventilator_DrehzahlMin;
gBetriebsparameter.Ventilator.DrehzahlMax := Par_Ventilator_DrehzahlMax;
gBetriebsparameter.Ventilator.DrehzahlBeiAuskuehlphase := Par_Ventilator_DrehzahlBeiAuskuehlphase;
gBetriebsparameter.Ventilator.DrzUmschaltung := Par_Ventilator_DrzUmschaltung;
gBetriebsparameter.Ventilator.DrehzahlFixLuftaufbereiter := Par_Ventilator_DrehzahlFixLuftaufbereiter;
gBetriebsparameter.Ventilator.DrehzahlFixFrischluft := Par_Ventilator_DrehzahlFixFrischluft;
gBetriebsparameter.Ventilator.DrehzahlStrombegrenzung := Par_Ventilator_DrehzahlStrombegrenzung;
gBetriebsparameter.Ventilator.DrehzahlLeistungsreduziert := Par_Ventilator_DrehzahlLeistungsreduz;
gBetriebsparameter.Ventilator.ZeitRampeUp := Par_Ventilator_ZeitRampeUp;
gBetriebsparameter.Ventilator.ZeitRampeDown := Par_Ventilator_ZeitRampeDown;


(*
---------------------------------------------------------------------------
Luftaufbereitung
---------------------------------------------------------------------------
*)

//Allgemein
gBetriebsparameter.Luftaufbereitung.VerzWetterwechsel := Par_Luftaufbereitung_VerzWetterwechsel;
gBetriebsparameter.Luftaufbereitung.SaettigungFrischluftEin := Par_Luftaufbereitung_SaettigungFrischlEin;
gBetriebsparameter.Luftaufbereitung.Hysterese := Par_Luftaufbereitung_Hysterese;
gBetriebsparameter.Luftaufbereitung.AutomatikbetriebEin:= Par_Luftaufbereitung_AutomatikbetriebEin;
gBetriebsparameter.Luftaufbereitung.DauerbetriebEin := Par_Luftaufbereitung_DauerbetriebEin;
gBetriebsparameter.Luftaufbereitung.Aus := Par_Luftaufbereitung_Aus;
//Spezifisch Heizregister
gBetriebsparameter.Luftaufbereitung.P := Par_Luftaufbereitung_P;
gBetriebsparameter.Luftaufbereitung.I := Par_Luftaufbereitung_I;
gBetriebsparameter.Luftaufbereitung.D := Par_Luftaufbereitung_D;
gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMin := Par_Luftaufbereitung_DrehzahlVorgabeMin;
gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMax := Par_Luftaufbereitung_DrehzahlVorgabeMax;
gBetriebsparameter.Luftaufbereitung.TempVorgabeSoll := Par_Luftaufbereitung_TempVorgabeSoll;
//Spezifisch Ofen
gBetriebsparameter.Luftaufbereitung.VerzBetriebsmeldung := Par_Luftaufbereitung_VerzBetriebsmeldung;
gBetriebsparameter.Luftaufbereitung.Auskuehlzeit := Par_Luftaufbereitung_Auskuehlzeit;



(*
---------------------------------------------------------------------------
Klappen/Boxen
---------------------------------------------------------------------------
*)
gBetriebsparameter.KlappenBoxen[1].Laufzeit := Klappen_Boxen_Box1_Laufzeit;
gBetriebsparameter.KlappenBoxen[2].Laufzeit := Klappen_Boxen_Box2_Laufzeit;

(*
---------------------------------------------------------------------------
Luftaufbereitung Allgemein
---------------------------------------------------------------------------
*)
gBetriebsparameter.Luftaufbereitung.Typ := Ausstattung_Luftaufbereiter_Typ;

(*
---------------------------------------------------------------------------
Strombegrenzung
---------------------------------------------------------------------------
*)
gBetriebsparameter.Strombegrenzung.StartStd := Par_Strombegrenzung_StartMin;
gBetriebsparameter.Strombegrenzung.StartMin := Par_Strombegrenzung_StartStd;
gBetriebsparameter.Strombegrenzung.StoppStd := Par_Strombegrenzung_StoppMin;
gBetriebsparameter.Strombegrenzung.StoppMin := Par_Strombegrenzung_StoppStd;

(*
---------------------------------------------------------------------------
Tarifabschaltung
---------------------------------------------------------------------------
*)
gBetriebsparameter.Tarifabschaltung.Zeitfenster.StartStd := Par_Tarifabschaltung_Start_Std;
gBetriebsparameter.Tarifabschaltung.Zeitfenster.StartMin := Par_Tarifabschaltung_Start_Min;
gBetriebsparameter.Tarifabschaltung.Zeitfenster.StoppStd := Par_Tarifabschaltung_Stopp_Std;
gBetriebsparameter.Tarifabschaltung.Zeitfenster.StoppMin := Par_Tarifabschaltung_Stopp_Min;

(*
-------------------------------------------------------------------------------
 Betriebsart / allgemeiner Zustand
-------------------------------------------------------------------------------
*)
HMI_TEST_diIoTestAktiv:= (gAktModus = IOTEST);

(*
-------------------------------------------------------------------------------
 Digitale Eingänge an HMI übergeben
-------------------------------------------------------------------------------
*)
HMI_IN_diBox1Offen  		:= diBox1Offen;
HMI_IN_diBox1Geschl  		:= diBox1Geschl;
HMI_IN_diBox2Offen  		:= diBox2Offen;
HMI_IN_diBox2Geschl 		:= diBox2Geschl;
HMI_IN_diBetriebLuftaufber 	:= diBetriebLuftaufber;
HMI_IN_diBetriebVentilator 	:= diBetriebVentilator;

(*
-------------------------------------------------------------------------------
 Analoge Eingänge an HMI übergeben
-------------------------------------------------------------------------------
 Es werden bereits skalierte Engineering-Werte an die HMI übergeben.
-------------------------------------------------------------------------------
*)
HMI_IN_aiFrischluftTemp       := gStatusAnlage.FrischluftTemperatur;
HMI_IN_aiFrischluftFeuchte    := gStatusAnlage.FrischluftFeuchte;
HMI_IN_aiAbluftBox1Temp       := gStatusAnlage.AbluftBox1Temp;
HMI_IN_aiAbluftBox1Feuchte    := gStatusAnlage.AbluftBox1Feuchte;
HMI_IN_aiTrockenluftTemp      := gStatusAnlage.TrockenluftTemperatur;
HMI_IN_aiTrockenluftFeuchte   := gStatusAnlage.TrockenluftFeuchte;
HMI_IN_aiAbluftBox2Temp       := gStatusAnlage.AbluftBox2Temp;
HMI_IN_aiAbluftBox2Feuchte    := gStatusAnlage.AbluftBox2Feuchte;
HMI_IN_aiStocktemp            := gStatusAnlage.StockTemperatur;


(*
-------------------------------------------------------------------------------
 Digitale Ausgänge an HMI übergeben
-------------------------------------------------------------------------------
 Hier werden die internen Soll-/Freigabesignale visualisiert.
-------------------------------------------------------------------------------
*)
HMI_IN_doFrgLuftaufber     		:= doFrgLuftaufber;
HMI_IN_doFrgBox1            	:= doFrgBox1;
HMI_IN_doFrgBox2           		:= doFrgBox2;
HMI_IN_doFrgAbluftvent	     	:= doFrgAbluftventilator;
HMI_IN_doFrgVentilator	     	:= doFrgVentilator;

(*
-------------------------------------------------------------------------------
 Analogausgänge an HMI übergeben
-------------------------------------------------------------------------------
 Die HMI erhält die Engineering-Sollwerte sowie optional die bereits
 skalierten Hardwarewerte.
-------------------------------------------------------------------------------
*)
HMI_IN_aoFuVentilator   	  := aoFuVentilator;
HMI_IN_aoLeistVorgLuftaufber  := aoLeistVorgLuftaufber;

(*
-------------------------------------------------------------------------------
 I/O-Testdaten an HMI übergeben
-------------------------------------------------------------------------------
 So sieht man in der Visu sofort, ob Testbetrieb aktiv ist und welche
 Testwerte gerade anliegen.
-------------------------------------------------------------------------------
*)

(* PLC OUT - HMI IN *)

//digital
HMI_TEST_diBox1Offen     		:= gIoTest.DigitalIn.diBox1Offen;
HMI_TEST_diBox1Geschl  	 		:= gIoTest.DigitalIn.diBox1Geschl;
HMI_TEST_diBox2Offen   		 	:= gIoTest.DigitalIn.diBox2Offen;
HMI_TEST_diBox2Geschl    		:= gIoTest.DigitalIn.diBox2Geschl;
HMI_TEST_diBetriebLuftaufber  	:= gIoTest.DigitalIn.diBetriebLuftaufber;
HMI_TEST_diBetriebVentilator 	:= gIoTest.DigitalIn.diBetriebVentilator;

//analog
HMI_TEST_aiFrischluftTemp  		:= gIoTest.AnalogIn.aiFrischluftTemp;
HMI_TEST_aiFrischluftFeuchte  	:= gIoTest.AnalogIn.aiFrischluftFeuchte;
HMI_TEST_aiAbluftBox1Temp     	:= gIoTest.AnalogIn.aiAbluftBox1Temp;
HMI_TEST_aiAbluftBox1Feuchte  	:= gIoTest.AnalogIn.aiAbluftBox1Feucht;
HMI_TEST_aiTrockenluftTemp 	  	:= gIoTest.AnalogIn.aiTrockenluftTemp;
HMI_TEST_aiTrockenluftFeuchte 	:= gIoTest.AnalogIn.aiTrockenluftFeucht;
HMI_TEST_aiAbluftBox2Temp  	  	:= gIoTest.AnalogIn.aiAbluftBox2Temp;
HMI_TEST_aiAbluftBox2Feuchte  	:= gIoTest.AnalogIn.aiAbluftBox2Feucht;
HMI_TEST_aiStocktemp   		  	:= gIoTest.AnalogIn.aiStocktemp;

(* HMI IN - PLC OUT *)

//digital
gIoTest.DigitalOut.doFrgLuftaufber			:= HMI_TEST_doFrgLuftaufber;
gIoTest.DigitalOut.doFrgBox1				:= HMI_TEST_doFrgBox1;
gIoTest.DigitalOut.doFrgBox2				:= HMI_TEST_doFrgBox2;
gIoTest.DigitalOut.doFrgAbluftventilator	:= HMI_TEST_doFrgAbluftventilator;
gIoTest.DigitalOut.doFrgVentilator			:= HMI_TEST_doFrgVentilator;

//analog
gIoTest.AnalogOut.aoFuVentilator			:= HMI_TEST_aoFuVentilator;
gIoTest.AnalogOut.aoLeistVorgLuftaufber 	:= HMI_TEST_aoLeistVorgLuftaufber;

(*
================================================================================
File        : StartStoppCyclic.st
Project     : CControl_Lite
Description :
    Start-/Stopp-Auswertung für 2-Box-Lite-Anlage.
================================================================================
*)

(* Betriebsart *)
gCmdAnlage.Auto := NOT HMI_TEST_doIoTestAktivieren;
gCmdAnlage.Test := HMI_TEST_doIoTestAktivieren;

(* Boxaktivität *)
xBox1Aktiv := (diBox1Offen OR gAktoren.Box[1].xSollOffen);

IF gBetriebsparameter.Ausstattung.Box2 THEN
    xBox2Aktiv := (diBox2Offen OR gAktoren.Box[2].xSollOffen);
ELSE
    xBox2Aktiv := FALSE;
END_IF;

xMindEineBoxAktiv := xBox1Aktiv OR xBox2Aktiv; //TODO RIG: Boxenkonfig muss noch implementiert werden!

(* externe Signale optional, muessen beschrieben werden wenn gewuenscht *)
xExternStart := gCmdAnlage.StartExtern;
xExternStop  := gCmdAnlage.StoppExtern;

(* Fehlerstopp vorerst ohne Alarmmatrix, Variable wird in AlarmCyclic beschrieben *)
//gCmdAnlage.FehlerStopp := FALSE;

(* Start/Stop *)
gCmdAnlage.Start := gCmdAnlage.Auto
                    AND (xMindEineBoxAktiv OR xExternStart)
                    AND NOT gCmdAnlage.FehlerStopp;

gCmdAnlage.Stopp := gCmdAnlage.Auto
                    AND ((NOT xMindEineBoxAktiv) OR xExternStop OR gCmdAnlage.FehlerStopp);

data.iecDecl:
PROGRAM StartStoppCyclic

VAR
    xBox1Aktiv : BOOL;
    xBox2Aktiv : BOOL;
    xMindEineBoxAktiv : BOOL;
    xExternStart : BOOL;
    xExternStop : BOOL;
END_VAR

ST.xhtml:p:
(*
================================================================================
 File        : fbBoxenklappe.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-04-03
 Version     : V0.02
 Description :
    Funktionsbaustein zur Ansteuerung einer Boxenklappe mit einem Wechsler-
    Relais.

    Funktionsprinzip:
      - nicht angesteuert = Richtung A
      - angesteuert       = Richtung B

    Für die Anwendung in CControl_Lite gilt:
      - OeffnenOut     = TRUE
      - SchliessenOut  = FALSE

    Funktionsumfang:
      - Laufzeitüberwachung Öffnen/Schließen
      - Fehlerquittierung
      - Endlagenbehandlung
      - Betrieb auch ohne Endlagen möglich
      - 40 ms Anzugsverzögerung

================================================================================
 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author          | Description
--------------------------------------------------------------------------------
 V0.02   | 2026-04-03 | RIG Automation  | Initialerstellung
================================================================================
*)

IF (NOT Stoerung) THEN

    (*
    ---------------------------------------------------------------------------
    Fehlerquittierung Laufzeitüberwachung
    ---------------------------------------------------------------------------
    *)
    IF QuitFehler OR (LaufzeitOeffnen = 0) OR (NOT EndlagenVhd) THEN
        FehlerLaufzeitOeffnen := FALSE;
    END_IF;

    IF QuitFehler OR (LaufzeitSchliessen = 0) OR (NOT EndlagenVhd) THEN
        FehlerLaufzeitSchliessen := FALSE;
    END_IF;


    CASE uiStep OF

        (*
        =======================================================================
        WARTEN
        =======================================================================
        *)
        0:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
            END_IF;

            (* state during *)
            IF QuitFehler OR (LaufzeitOeffnen = 0) OR (NOT EndlagenVhd) THEN
                FehlerLaufzeitOeffnen := FALSE;
            END_IF;

            IF QuitFehler OR (LaufzeitSchliessen = 0) OR (NOT EndlagenVhd) THEN
                FehlerLaufzeitSchliessen := FALSE;
            END_IF;

            (* state exit *)
            IF EndlagenVhd OR (LaufzeitOeffnen = 0) THEN
                IF Oeffnen AND NOT FehlerLaufzeitOeffnen THEN
                    stateEntry := TRUE;
                    uiStep  := 1;
                END_IF;
            ELSE
                IF Oeffnen AND NOT KlappeIstOffenOut THEN
                    stateEntry := TRUE;
                    uiStep  := 1;
                END_IF;
            END_IF;

            IF EndlagenVhd OR (LaufzeitSchliessen = 0) THEN
                IF Schliessen AND NOT FehlerLaufzeitSchliessen THEN
                    stateEntry := TRUE;
                    uiStep  := 2;
                END_IF;
            ELSE
                IF Schliessen AND NOT KlappeIstGeschlOut THEN
                    stateEntry := TRUE;
                    uiStep := 2;
                END_IF;
            END_IF;


        (*
        =======================================================================
        OEFFNEN
        =======================================================================
        *)
        1:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
                FehlerLaufzeitOeffnen := FALSE;
                FehlerLaufzeitSchliessen := FALSE;
                SchliessenOut := FALSE;
                KlappeIstGeschlOut := FALSE;
                KlappeIstOffenOut := FALSE;
            END_IF;

            (* state during *)
            TON_Laufzeit(IN := OeffnenOut AND NOT EndlageOffen, PT := LaufzeitOeffnen);
            TON_AnzVerz(IN := TRUE, PT := 40);
            OeffnenOut := TON_AnzVerz.Q;

            (* state exit *)
            IF (NOT Oeffnen) OR Schliessen OR (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0)) THEN
                IF (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0) AND NOT EndlagenVhd) THEN
                    KlappeIstOffenOut := TRUE;
                ELSIF (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0)) THEN
                    FehlerLaufzeitOeffnen := TRUE;
                END_IF;

                stateEntry := TRUE;
                uiStep  := 0;
            END_IF;


        (*
        =======================================================================
        SCHLIESSEN
        =======================================================================
        *)
        2:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
                FehlerLaufzeitOeffnen := FALSE;
                FehlerLaufzeitSchliessen := FALSE;
                OeffnenOut := FALSE;
                KlappeIstGeschlOut := FALSE;
                KlappeIstOffenOut := FALSE;
            END_IF;

            (* state during *)
            TON_Laufzeit(IN := SchliessenOut AND NOT EndlageGeschl, PT := LaufzeitSchliessen);
            TON_AnzVerz(IN := TRUE, PT := 40);
            SchliessenOut := TON_AnzVerz.Q;

            (* state exit *)
            IF (NOT Schliessen) OR Oeffnen OR (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0)) THEN
                IF (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0) AND NOT EndlagenVhd) THEN
                    KlappeIstGeschlOut := TRUE;
                ELSIF (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0)) THEN
                    FehlerLaufzeitSchliessen := TRUE;
                END_IF;

                stateEntry := TRUE;
                uiStep := 0;
            END_IF;

    END_CASE;

ELSE
    OeffnenOut := FALSE;
    SchliessenOut := FALSE;
    stateEntry := TRUE;
    FehlerLaufzeitOeffnen := FALSE;
    FehlerLaufzeitSchliessen := FALSE;
    KlappeIstGeschlOut := FALSE;
    KlappeIstOffenOut := FALSE;
    uiStep := 0;
END_IF;

IF (Freigabe = TRUE) THEN
    // Zeitfenster 1 ********************************************************
    FreigZeitfenster1 := FALSE;
    IF (StartZeit1 > StoppZeit1) THEN
        IF (AktZeit >= StartZeit1) OR (AktZeit < StoppZeit1) THEN
            FreigZeitfenster1 := TRUE;
        END_IF;
    ELSE
        IF (AktZeit >= StartZeit1) AND (AktZeit < StoppZeit1) THEN
            FreigZeitfenster1 := TRUE;
        END_IF;
    END_IF;
    // Zeitfenster 2 ********************************************************
    FreigZeitfenster2 := FALSE;
    IF (StartZeit2 > StoppZeit2) THEN
        IF (AktZeit >= StartZeit2) OR (AktZeit < StoppZeit2) THEN
            FreigZeitfenster2 := TRUE;
        END_IF;
    ELSE
        IF (AktZeit >= StartZeit2) AND (AktZeit < StoppZeit2) THEN
            FreigZeitfenster2 := TRUE;
        END_IF;
    END_IF;
    // Zeitfenster 3 ********************************************************
    FreigZeitfenster3 := FALSE;
    IF (StartZeit3 > StoppZeit3) THEN
        IF (AktZeit >= StartZeit3) OR (AktZeit < StoppZeit3) THEN
            FreigZeitfenster3 := TRUE;
        END_IF;
    ELSE
        IF (AktZeit >= StartZeit3) AND (AktZeit < StoppZeit3) THEN
            FreigZeitfenster3 := TRUE;
        END_IF;
    END_IF;
    // Drehzahlbegrenzungen 1 - 3
    IF (FreigZeitfenster1) THEN
        DrehzahlBegrenzung := DrehzahlBegrenzung1;
    ELSIF (FreigZeitfenster2) THEN
        DrehzahlBegrenzung := DrehzahlBegrenzung2;
    ELSIF (FreigZeitfenster3) THEN
        DrehzahlBegrenzung := DrehzahlBegrenzung3;
    ELSE
        DrehzahlBegrenzung := 0.0;
    END_IF;
    StrombegrenzungEin := FreigZeitfenster1 OR FreigZeitfenster2 OR FreigZeitfenster3;
ELSE
    FreigZeitfenster1  := FALSE;
    FreigZeitfenster2  := FALSE;
    FreigZeitfenster3  := FALSE;
    StrombegrenzungEin := FALSE;
    DrehzahlBegrenzung := 0.0;
END_IF;

//Auskühlzeit Warmluftofen, wenn Option Betriebsmeldung nicht vorhanden
TOF_Auskuehlzeit(IN := FreigabeWarmluftofenOut, PT := Auskuehlzeit);

//Restlaufzeit Auskühlung berechnen (für Visu)
RestAuskuehlzeit := Auskuehlzeit - TO_UDINT(TOF_Auskuehlzeit.ET);

//Ausgang für Warmluftofen aktiv
WarmluftofenAktiv := (TOF_Auskuehlzeit.Q AND NOT OptionBetriebsmldgVhd)
                     OR (BetriebsmeldungWarmluftofen AND OptionBetriebsmldgVhd)
                     OR FreigabeWarmluftofenOut;

//Fehlerquittierung
IF QuitFehler THEN
    FehlerSensorAussenluftOut := FALSE;
    FehlerBetriebsmeldungOut  := FALSE;
END_IF;


IF Freigabe THEN

    CASE uStep OF

        //AUS *********************************************************************************************
        0:
            IF stateEntry THEN
                stateEntry              := FALSE;
                FreigabeWarmluftofenOut := FALSE;
                WarmlufttempSollOut     := 0.0;
                TON_VerzBetriebsmeldung(IN := FALSE, PT := 0);
            END_IF;

            //Automatikbetrieb aktiviert
            IF Automatikbetrieb AND NOT FehlerSensorAussenluftOut AND NOT FehlerBetriebsmeldungOut AND NOT FehlerSensorAussenluft THEN
                stateEntry := TRUE;
                uStep       := 1;
            ELSIF Dauerbetrieb AND NOT FehlerSensorAussenluftOut AND NOT FehlerBetriebsmeldungOut THEN
                stateEntry := TRUE;
                uStep       := 2;
            END_IF;


        //AUTOMATIKBETRIEB ********************************************************************************
        1:
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_VerzBetriebsmeldung(IN := FALSE, PT := 0);
            END_IF;

            //Bei Neustart (Wetter nicht gut oder schlecht) ohne Verzögerung umschalten
            IF NOT loc_WetterIstSchlecht AND NOT loc_WetterIstGut THEN
                IF (FrischluftSattDefizitIst < FrischluftSattDefizitSoll) THEN
                    loc_WetterIstSchlecht := TRUE;
                ELSIF (FrischluftSattDefizitIst >= FrischluftSattDefizitSoll) THEN
                    loc_WetterIstGut := TRUE;
                END_IF;
            END_IF;

            //Umschaltverzögerung gutes Wetter / schlechtes Wetter
            TON_WetterIstGut(IN := loc_WetterIstSchlecht AND (FrischluftSattDefizitIst >= (FrischluftSattDefizitSoll + Hysterese)), PT := UmschaltverzWitterung);
            TON_WetterIstSchlecht(IN := loc_WetterIstGut AND (FrischluftSattDefizitIst < (FrischluftSattDefizitSoll - Hysterese)), PT := UmschaltverzWitterung);

            //Flankenauswertung (ersetzt EDGEPOS)
            R_TRIG_WetterIstGut(CLK := TON_WetterIstGut.Q);
            R_TRIG_WetterIstSchlecht(CLK := TON_WetterIstSchlecht.Q);

            IF R_TRIG_WetterIstGut.Q THEN
                loc_WetterIstGut      := TRUE;
                loc_WetterIstSchlecht := FALSE;
            ELSIF R_TRIG_WetterIstSchlecht.Q THEN
                loc_WetterIstGut      := FALSE;
                loc_WetterIstSchlecht := TRUE;
            END_IF;

            //Freigabe Warmluftofen
            FreigabeWarmluftofenOut := loc_WetterIstSchlecht OR WetterIstSchlecht;
            WarmlufttempSollOut     := WarmlufttemperaturVorgabe;

            //Verzögerung Überwachung Betriebsmeldung (Zündzeit)
            TON_VerzBetriebsmeldung(IN := FreigabeWarmluftofenOut AND OptionBetriebsmldgVhd AND NOT BetriebsmeldungWarmluftofen, PT := VerzBetriebsmeldung);

            //Fehler keine Betriebsmeldung
            IF TON_VerzBetriebsmeldung.Q THEN
                FehlerBetriebsmeldungOut := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Fehler Sensor Frischluft
            ELSIF FehlerSensorAussenluft THEN
                FehlerSensorAussenluftOut := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Dauerbetrieb aktiv
            ELSIF Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 2;
            //Kein Automatikbetrieb
            ELSIF NOT Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;


        //DAUERBETRIEB ***********************************************************************************
        2:
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_VerzBetriebsmeldung(IN := FALSE, PT := 0);
            END_IF;

            //Freigabe Warmluftofen
            FreigabeWarmluftofenOut := TRUE;
            WarmlufttempSollOut     := WarmlufttemperaturVorgabe;

            //Verzögerung Überwachung Betriebsmeldung (Zündzeit)
            TON_VerzBetriebsmeldung(IN := FreigabeWarmluftofenOut AND OptionBetriebsmldgVhd AND NOT BetriebsmeldungWarmluftofen, PT := VerzBetriebsmeldung);

            //Fehler
            IF TON_VerzBetriebsmeldung.Q THEN
                FehlerBetriebsmeldungOut := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Automatikbetrieb aktiv
            ELSIF Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 1;
            //Kein Dauerbetrieb
            ELSIF NOT Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;

    END_CASE;

ELSE

    FreigabeWarmluftofenOut   := FALSE;
    WarmlufttempSollOut       := 0.0;
    uStep                      := 0;
    stateEntry                := TRUE;
    FehlerSensorAussenluftOut := FALSE;
    FehlerBetriebsmeldungOut  := FALSE;

END_IF;

IF Freigabe THEN

    //Fehlerquittierung
    IF QuitFehler THEN
        FehlerOut := FALSE;
    END_IF;


    CASE uStep OF

        //AUS *********************************************************************************************
        0:
            IF stateEntry THEN
                stateEntry              := FALSE;
                FreigabeHeizregisterOut := FALSE;
                DrehzahlHeizregisterOut := 0.0;
            END_IF;

            //Automatikbetrieb aktiviert
            IF Automatikbetrieb AND NOT FehlerOut AND NOT FehlerSensorAussenluft THEN
                stateEntry := TRUE;
                uStep       := 1;
            ELSIF Dauerbetrieb AND NOT FehlerOut THEN
                stateEntry := TRUE;
                uStep       := 2;
            END_IF;


        //AUTOMATIKBETRIEB ********************************************************************************
        1:
            IF stateEntry THEN
                stateEntry := FALSE;
            END_IF;

            //Bei Neustart (Wetter nicht gut oder schlecht) ohne Verzögerung umschalten
            IF NOT loc_WetterIstSchlecht AND NOT loc_WetterIstGut THEN
                IF (FrischluftSattDefizitIst < FrischluftSattDefizitSoll) THEN
                    loc_WetterIstSchlecht := TRUE;
                ELSIF (FrischluftSattDefizitIst >= FrischluftSattDefizitSoll) THEN
                    loc_WetterIstGut := TRUE;
                END_IF;
            END_IF;

            //Umschaltverzögerung gutes Wetter / schlechtes Wetter
            TON_WetterIstGut(IN := loc_WetterIstSchlecht AND (FrischluftSattDefizitIst >= (FrischluftSattDefizitSoll + Hysterese)), PT := UmschaltverzWitterung);
            TON_WetterIstSchlecht(IN := loc_WetterIstGut AND (FrischluftSattDefizitIst < (FrischluftSattDefizitSoll - Hysterese)), PT := UmschaltverzWitterung);

            //Flankenauswertung (ersetzt EDGEPOS)
            R_TRIG_WetterIstGut(CLK := TON_WetterIstGut.Q);
            R_TRIG_WetterIstSchlecht(CLK := TON_WetterIstSchlecht.Q);

            IF R_TRIG_WetterIstGut.Q THEN
                loc_WetterIstGut      := TRUE;
                loc_WetterIstSchlecht := FALSE;
            ELSIF R_TRIG_WetterIstSchlecht.Q THEN
                loc_WetterIstGut      := FALSE;
                loc_WetterIstSchlecht := TRUE;
            END_IF;

            //Freigabe Heizregister
            FreigabeHeizregisterOut := loc_WetterIstSchlecht OR WetterIstSchlecht;
            DrehzahlHeizregisterOut := DrehzahlHeizregisterSoll;

            //Fehler
            IF FehlerSensorAussenluft THEN
                FehlerOut  := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Dauerbetrieb aktiv
            ELSIF Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 2;
            //Kein Automatikbetrieb
            ELSIF NOT Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;


        //DAUERBETRIEB ***********************************************************************************
        2:
            IF stateEntry THEN
                stateEntry := FALSE;
            END_IF;

            //Freigabe Heizregister
            FreigabeHeizregisterOut := TRUE;
            DrehzahlHeizregisterOut := DrehzahlHeizregisterSoll;

            //Automatikbetrieb aktiv
            IF Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 1;
            //Kein Dauerbetrieb
            ELSIF NOT Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;

    END_CASE;


ELSE

    FreigabeHeizregisterOut := FALSE;
    DrehzahlHeizregisterOut := 0.0;
    uStep                    := 0;
    stateEntry              := TRUE;
    FehlerOut               := FALSE;

END_IF;
